import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';

export class BookStore {
  constructor(filePath) {
    this.filePath = filePath || path.resolve(process.cwd(), 'data', 'books.json');
  }

  async ensureFile() {
    try {
      await fs.access(this.filePath);
    } catch {
      await fs.mkdir(path.dirname(this.filePath), { recursive: true });
      await fs.writeFile(this.filePath, JSON.stringify([], null, 2), 'utf8');
    }
  }

  async getAll() {
    await this.ensureFile();
    const raw = await fs.readFile(this.filePath, 'utf8');
    try {
      const data = JSON.parse(raw);
      return Array.isArray(data) ? data : [];
    } catch {
      return [];
    }
  }

  async saveAll(books) {
    await fs.mkdir(path.dirname(this.filePath), { recursive: true });
    await fs.writeFile(this.filePath, JSON.stringify(books, null, 2), 'utf8');
  }

  async getById(id) {
    const books = await this.getAll();
    return books.find((b) => b.id === id) || null;
  }

  async addBook({ title, author, notes = '', status = 'reading' }) {
    const cleanTitle = (title || '').trim();
    const cleanAuthor = (author || '').trim();
    if (!cleanTitle || !cleanAuthor) {
      throw new Error('Title and author are required');
    }

    const books = await this.getAll();
    const now = new Date().toISOString();
    const normalizedStatus = status === 'finished' ? 'finished' : 'reading';
    const book = {
      id: crypto.randomUUID().slice(0, 8),
      title: cleanTitle,
      author: cleanAuthor,
      notes: (notes || '').trim(),
      status: normalizedStatus,
      createdAt: now,
      finishedAt: normalizedStatus === 'finished' ? now : null,
    };

    books.unshift(book);
    await this.saveAll(books);
    return book;
  }

  async updateBook(id, updates) {
    const books = await this.getAll();
    const index = books.findIndex((b) => b.id === id);
    if (index === -1) return null;

    const existing = books[index];
    const nextStatus =
      updates.status !== undefined
        ? updates.status === 'finished'
          ? 'finished'
          : 'reading'
        : existing.status;

    let finishedAt = existing.finishedAt;
    if (nextStatus === 'finished' && existing.status !== 'finished') {
      finishedAt = new Date().toISOString();
    } else if (nextStatus === 'reading') {
      finishedAt = null;
    }

    const updated = {
      ...existing,
      title: updates.title !== undefined ? String(updates.title).trim() || existing.title : existing.title,
      author: updates.author !== undefined ? String(updates.author).trim() || existing.author : existing.author,
      notes: updates.notes !== undefined ? String(updates.notes) : existing.notes,
      status: nextStatus,
      finishedAt,
    };

    books[index] = updated;
    await this.saveAll(books);
    return updated;
  }

  async deleteBook(id) {
    const books = await this.getAll();
    const next = books.filter((b) => b.id !== id);
    if (next.length === books.length) return false;
    await this.saveAll(next);
    return true;
  }
}

