import http from 'node:http';
import { URL } from 'node:url';
import { BookStore } from './store.js';

function escapeHtml(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > 1e6) {
        req.destroy();
        reject(new Error('Body too large'));
      }
    });
    req.on('end', () => {
      if (!raw) return resolve({});
      const contentType = (req.headers['content-type'] || '').toLowerCase();
      if (contentType.includes('application/json')) {
        try {
          resolve(JSON.parse(raw));
        } catch (err) {
          reject(new Error('Invalid JSON'));
        }
      } else {
        const params = new URLSearchParams(raw);
        resolve(Object.fromEntries(params.entries()));
      }
    });
    req.on('error', reject);
  });
}

function sendJson(res, status, data) {
  const payload = JSON.stringify(data);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function renderLayout(title, bodyContent) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${escapeHtml(title)}</title>
  <style>
    :root {
      --bg: #faf8f5;
      --card: #ffffff;
      --border: #e6e1d6;
      --text: #1f1e1b;
      --muted: #6e6a63;
      --accent: #2c5e43;
      --accent-hover: #214732;
      --badge-reading-bg: #eef5f0;
      --badge-reading-text: #2c5e43;
      --badge-finished-bg: #f3efe6;
      --badge-finished-text: #5c5346;
      --danger: #a63a3a;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Georgia, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
    }
    header {
      border-bottom: 1px solid var(--border);
      background: var(--card);
    }
    .container {
      max-width: 820px;
      margin: 0 auto;
      padding: 1.5rem 1.25rem;
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 1rem;
      padding-bottom: 1rem;
    }
    .brand {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--text);
      text-decoration: none;
      letter-spacing: -0.02em;
    }
    h1, h2, h3 {
      margin-top: 0;
      letter-spacing: -0.01em;
    }
    .card {
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1.25rem;
      margin-bottom: 1.5rem;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    }
    .form-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0.75rem;
    }
    @media (max-width: 600px) {
      .form-grid { grid-template-columns: 1fr; }
    }
    .field {
      margin-bottom: 0.75rem;
    }
    label {
      display: block;
      font-size: 0.875rem;
      font-weight: 600;
      margin-bottom: 0.25rem;
    }
    input[type="text"], textarea, select {
      width: 100%;
      padding: 0.55rem 0.7rem;
      border: 1px solid var(--border);
      border-radius: 6px;
      font-size: 0.95rem;
      font-family: inherit;
      background: #fff;
      color: var(--text);
    }
    textarea {
      min-height: 90px;
      resize: vertical;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.35rem;
      padding: 0.5rem 0.95rem;
      font-size: 0.9rem;
      font-weight: 600;
      border-radius: 6px;
      border: 1px solid transparent;
      cursor: pointer;
      text-decoration: none;
      font-family: inherit;
      background: var(--accent);
      color: #fff;
    }
    .btn:hover {
      background: var(--accent-hover);
    }
    .btn-secondary {
      background: transparent;
      border-color: var(--border);
      color: var(--text);
    }
    .btn-secondary:hover {
      background: #f3efe6;
    }
    .btn-danger {
      background: transparent;
      border-color: #e6caca;
      color: var(--danger);
    }
    .btn-danger:hover {
      background: #fdf2f2;
    }
    .book-list {
      list-style: none;
      padding: 0;
      margin: 0;
      display: grid;
      gap: 0.75rem;
    }
    .book-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem;
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 8px;
    }
    .book-info {
      min-width: 0;
      flex: 1;
    }
    .book-title {
      font-weight: 600;
      font-size: 1.05rem;
      color: var(--text);
      text-decoration: none;
      display: inline-block;
    }
    .book-title:hover {
      color: var(--accent);
      text-decoration: underline;
    }
    .book-author {
      color: var(--muted);
      font-size: 0.9rem;
      margin-top: 0.15rem;
    }
    .book-notes-preview {
      color: var(--muted);
      font-size: 0.85rem;
      margin-top: 0.35rem;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .book-actions {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-shrink: 0;
    }
    .badge {
      display: inline-block;
      padding: 0.2rem 0.6rem;
      font-size: 0.75rem;
      font-weight: 600;
      border-radius: 999px;
    }
    .badge-reading {
      background: var(--badge-reading-bg);
      color: var(--badge-reading-text);
    }
    .badge-finished {
      background: var(--badge-finished-bg);
      color: var(--badge-finished-text);
    }
    .empty-state {
      color: var(--muted);
      font-size: 0.95rem;
      padding: 1rem;
      border: 1px dashed var(--border);
      border-radius: 8px;
      text-align: center;
    }
    .section-header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin-bottom: 0.75rem;
      margin-top: 1.5rem;
    }
    .count {
      font-size: 0.85rem;
      color: var(--muted);
      font-weight: normal;
    }
    .notes-box {
      white-space: pre-wrap;
      background: #fcfbf9;
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 1rem;
      margin: 1rem 0;
      min-height: 60px;
    }
    .share-bar {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-top: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--border);
    }
    .share-input {
      flex: 1;
      font-size: 0.85rem;
      color: var(--muted);
      background: #faf8f5;
    }
  </style>
</head>
<body>
  <header>
    <div class="container header-inner">
      <a href="/" class="brand">Reading Log</a>
    </div>
  </header>
  <main class="container">
    ${bodyContent}
  </main>
</body>
</html>`;
}

function renderHomePage(books) {
  const currentlyReading = books.filter((b) => b.status === 'reading');
  const finishedBooks = books.filter((b) => b.status === 'finished');

  const renderBookItem = (book) => {
    const actionBtn =
      book.status === 'reading'
        ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" style="margin:0;">
             <button type="submit" class="btn btn-secondary" data-action="finish" data-id="${escapeHtml(book.id)}">Mark as Finished</button>
           </form>`
        : `<span class="badge badge-finished">Finished</span>`;

    return `<li class="book-item" data-book-id="${escapeHtml(book.id)}">
      <div class="book-info">
        <a class="book-title" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
        <div class="book-author">by ${escapeHtml(book.author)}</div>
        ${book.notes ? `<div class="book-notes-preview">${escapeHtml(book.notes)}</div>` : ''}
      </div>
      <div class="book-actions">
        ${actionBtn}
      </div>
    </li>`;
  };

  const readingHtml =
    currentlyReading.length > 0
      ? `<ul class="book-list" id="currently-reading-list">${currentlyReading.map(renderBookItem).join('')}</ul>`
      : `<div class="empty-state" id="currently-reading-empty">No books currently being read. Add one above!</div>`;

  const finishedHtml =
    finishedBooks.length > 0
      ? `<ul class="book-list" id="finished-books-list">${finishedBooks.map(renderBookItem).join('')}</ul>`
      : `<div class="empty-state" id="finished-books-empty">No finished books yet.</div>`;

  const content = `
    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading" style="font-size: 1.1rem; margin-bottom: 0.85rem;">Add a Book</h2>
      <form id="add-book-form" method="POST" action="/books">
        <div class="form-grid">
          <div class="field">
            <label for="title">Title</label>
            <input type="text" id="title" name="title" required placeholder="e.g. The Left Hand of Darkness" />
          </div>
          <div class="field">
            <label for="author">Author</label>
            <input type="text" id="author" name="author" required placeholder="e.g. Ursula K. Le Guin" />
          </div>
        </div>
        <div class="field">
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="Thoughts, favorite quotes, or who recommended it..."></textarea>
        </div>
        <button type="submit" class="btn">Add Book</button>
      </form>
    </section>

    <section aria-labelledby="reading-heading">
      <div class="section-header">
        <h2 id="reading-heading" style="font-size: 1.2rem; margin: 0;">Currently Reading</h2>
        <span class="count">${currentlyReading.length} ${currentlyReading.length === 1 ? 'book' : 'books'}</span>
      </div>
      ${readingHtml}
    </section>

    <section aria-labelledby="finished-heading">
      <div class="section-header">
        <h2 id="finished-heading" style="font-size: 1.2rem; margin: 0;">Finished</h2>
        <span class="count">${finishedBooks.length} ${finishedBooks.length === 1 ? 'book' : 'books'}</span>
      </div>
      ${finishedHtml}
    </section>
  `;

  return renderLayout('Reading Log', content);
}

function renderBookPage(book, origin) {
  const shareUrl = `${origin}/books/${encodeURIComponent(book.id)}`;
  const isReading = book.status === 'reading';

  const statusBadge = isReading
    ? `<span class="badge badge-reading">Currently Reading</span>`
    : `<span class="badge badge-finished">Finished</span>`;

  const toggleStatusButton = isReading
    ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" style="display:inline; margin:0;">
         <button type="submit" class="btn">Mark as Finished</button>
       </form>`
    : `<form method="POST" action="/books/${encodeURIComponent(book.id)}/reopen" style="display:inline; margin:0;">
         <button type="submit" class="btn btn-secondary">Move to Currently Reading</button>
       </form>`;

  const content = `
    <div style="margin-bottom: 1rem;">
      <a href="/" class="btn btn-secondary" style="font-size: 0.85rem; padding: 0.35rem 0.7rem;">&larr; All Books</a>
    </div>

    <article class="card">
      <div style="display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; flex-wrap: wrap;">
        <div>
          <h1 style="margin: 0 0 0.25rem 0; font-size: 1.6rem;">${escapeHtml(book.title)}</h1>
          <div class="book-author" style="font-size: 1.05rem;">by ${escapeHtml(book.author)}</div>
        </div>
        <div style="display: flex; align-items: center; gap: 0.5rem;">
          ${statusBadge}
