    }
    .container {
      max-width: 820px;
      margin: 0 auto;
      padding: 1.5rem 1.25rem;
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 1rem;
      padding-bottom: 1rem;
    }
    .brand {
