    }
    .badge-finished {
      background: var(--badge-finished-bg);
      color: var(--badge-finished-text);
    }
    .empty-state {
      color: var(--muted);
      font-size: 0.95rem;
      padding: 1rem;
      border: 1px dashed var(--border);
      border-radius: 8px;
      text-align: center;
    }
    .section-header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin-bottom: 0.75rem;
      margin-top: 1.5rem;
    }
    .count {
      font-size: 0.85rem;
      color: var(--muted);
      font-weight: normal;
    }
    .notes-box {
      white-space: pre-wrap;
      background: #fcfbf9;
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 1rem;
      margin: 1rem 0;
      min-height: 60px;
    }
    .share-bar {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-top: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--border);
    }
