      flex: 1;
      font-size: 0.85rem;
      color: var(--muted);
      background: #faf8f5;
    }
  </style>
</head>
<body>
  <header>
    <div class="container header-inner">
      <a href="/" class="brand">Reading Log</a>
    </div>
