      --accent: #2c5e43;
      --accent-hover: #214732;
      --badge-reading-bg: #eef5f0;
      --badge-reading-text: #2c5e43;
      --badge-finished-bg: #f3efe6;
      --badge-finished-text: #5c5346;
      --danger: #a63a3a;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Georgia, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
    }
    header {
      border-bottom: 1px solid var(--border);
      background: var(--card);
    }
    .container {
      max-width: 820px;
      margin: 0 auto;
      padding: 1.5rem 1.25rem;
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 1rem;
      padding-bottom: 1rem;
    }
    .brand {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--text);
      text-decoration: none;
      letter-spacing: -0.02em;
    }
    h1, h2, h3 {
      margin-top: 0;
      letter-spacing: -0.01em;
    }
    .card {
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1.25rem;
      margin-bottom: 1.5rem;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    }
    .form-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0.75rem;
    }
    @media (max-width: 600px) {
      .form-grid { grid-template-columns: 1fr; }
    }
    .field {
      margin-bottom: 0.75rem;
    }
    label {
      display: block;
      font-size: 0.875rem;
      font-weight: 600;
      margin-bottom: 0.25rem;
    }
    input[type="text"], textarea, select {
      width: 100%;
      padding: 0.55rem 0.7rem;
      border: 1px solid var(--border);
      border-radius: 6px;
      font-size: 0.95rem;
      font-family: inherit;
      background: #fff;
      color: var(--text);
    }
    textarea {
      min-height: 90px;
      resize: vertical;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.35rem;
      padding: 0.5rem 0.95rem;
      font-size: 0.9rem;
      font-weight: 600;
      border-radius: 6px;
      border: 1px solid transparent;
      cursor: pointer;
      text-decoration: none;
      font-family: inherit;
      background: var(--accent);
      color: #fff;
    }
    .btn:hover {
      background: var(--accent-hover);
    }
    .btn-secondary {
      background: transparent;
      border-color: var(--border);
      color: var(--text);
    }
    .btn-secondary:hover {
      background: #f3efe6;
    }
    .btn-danger {
      background: transparent;
      border-color: #e6caca;
      color: var(--danger);
    }
    .btn-danger:hover {
      background: #fdf2f2;
    }
    .book-list {
      list-style: none;
      padding: 0;
      margin: 0;
      display: grid;
      gap: 0.75rem;
    }
    .book-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem;
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: 8px;
    }
    .book-info {
      min-width: 0;
      flex: 1;
    }
    .book-title {
      font-weight: 600;
      font-size: 1.05rem;
      color: var(--text);
      text-decoration: none;
      display: inline-block;
    }
    .book-title:hover {
      color: var(--accent);
      text-decoration: underline;
    }
    .book-author {
      color: var(--muted);
      font-size: 0.9rem;
      margin-top: 0.15rem;
    }
    .book-notes-preview {
      color: var(--muted);
      font-size: 0.85rem;
      margin-top: 0.35rem;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .book-actions {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-shrink: 0;
    }
    .badge {
      display: inline-block;
      padding: 0.2rem 0.6rem;
      font-size: 0.75rem;
      font-weight: 600;
      border-radius: 999px;
    }
    .badge-reading {
      background: var(--badge-reading-bg);
      color: var(--badge-reading-text);
    }
    .badge-finished {
      background: var(--badge-finished-bg);
      color: var(--badge-finished-text);
    }
    .empty-state {
      color: var(--muted);
      font-size: 0.95rem;
      padding: 1rem;
      border: 1px dashed var(--border);
      border-radius: 8px;
      text-align: center;
    }
    .section-header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      margin-bottom: 0.75rem;
      margin-top: 1.5rem;
    }
    .count {
      font-size: 0.85rem;
      color: var(--muted);
      font-weight: normal;
    }
    .notes-box {
      white-space: pre-wrap;
      background: #fcfbf9;
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 1rem;
      margin: 1rem 0;
      min-height: 60px;
    }
    .share-bar {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-top: 1rem;
      padding-top: 1rem;
      border-top: 1px solid var(--border);
    }
    .share-input {
      flex: 1;
      font-size: 0.85rem;
      color: var(--muted);
      background: #faf8f5;
    }
  </style>
</head>
<body>
  <header>
    <div class="container header-inner">
      <a href="/" class="brand">Reading Log</a>
    </div>
  </header>
  <main class="container">
    ${bodyContent}
  </main>
</body>
</html>`;
}

function renderHomePage(books) {
  const currentlyReading = books.filter((b) => b.status === 'reading');
  const finishedBooks = books.filter((b) => b.status === 'finished');

  const renderBookItem = (book) => {
    const actionBtn =
      book.status === 'reading'
        ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" style="margin:0;">
             <button type="submit" class="btn btn-secondary" data-action="finish" data-id="${escapeHtml(book.id)}">Mark as Finished</button>
           </form>`
        : `<span class="badge badge-finished">Finished</span>`;

    return `<li class="book-item" data-book-id="${escapeHtml(book.id)}">
      <div class="book-info">
        <a class="book-title" href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
        <div class="book-author">by ${escapeHtml(book.author)}</div>
        ${book.notes ? `<div class="book-notes-preview">${escapeHtml(book.notes)}</div>` : ''}
      </div>
      <div class="book-actions">
        ${actionBtn}
      </div>
    </li>`;
  };

  const readingHtml =
    currentlyReading.length > 0
      ? `<ul class="book-list" id="currently-reading-list">${currentlyReading.map(renderBookItem).join('')}</ul>`
      : `<div class="empty-state" id="currently-reading-empty">No books currently being read. Add one above!</div>`;

  const finishedHtml =
    finishedBooks.length > 0
      ? `<ul class="book-list" id="finished-books-list">${finishedBooks.map(renderBookItem).join('')}</ul>`
      : `<div class="empty-state" id="finished-books-empty">No finished books yet.</div>`;

  const content = `
    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading" style="font-size: 1.1rem; margin-bottom: 0.85rem;">Add a Book</h2>
      <form id="add-book-form" method="POST" action="/books">
        <div class="form-grid">
          <div class="field">
            <label for="title">Title</label>
            <input type="text" id="title" name="title" required placeholder="e.g. The Left Hand of Darkness" />
          </div>
          <div class="field">
            <label for="author">Author</label>
            <input type="text" id="author" name="author" required placeholder="e.g. Ursula K. Le Guin" />
          </div>
        </div>
        <div class="field">
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="Thoughts, favorite quotes, or who recommended it..."></textarea>
        </div>
        <button type="submit" class="btn">Add Book</button>
      </form>
    </section>

    <section aria-labelledby="reading-heading">
      <div class="section-header">
        <h2 id="reading-heading" style="font-size: 1.2rem; margin: 0;">Currently Reading</h2>
        <span class="count">${currentlyReading.length} ${currentlyReading.length === 1 ? 'book' : 'books'}</span>
      </div>
      ${readingHtml}
    </section>

    <section aria-labelledby="finished-heading">
      <div class="section-header">
        <h2 id="finished-heading" style="font-size: 1.2rem; margin: 0;">Finished</h2>
        <span class="count">${finishedBooks.length} ${finishedBooks.length === 1 ? 'book' : 'books'}</span>
      </div>
      ${finishedHtml}
    </section>
  `;

  return renderLayout('Reading Log', content);
}

function renderBookPage(book, origin) {
  const shareUrl = `${origin}/books/${encodeURIComponent(book.id)}`;
  const isReading = book.status === 'reading';

  const statusBadge = isReading
    ? `<span class="badge badge-reading">Currently Reading</span>`
    : `<span class="badge badge-finished">Finished</span>`;

  const toggleStatusButton = isReading
    ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" style="display:inline; margin:0;">
         <button type="submit" class="btn">Mark as Finished</button>
       </form>`
    : `<form method="POST" action="/books/${encodeURIComponent(book.id)}/reopen" style="display:inline; margin:0;">
         <button type="submit" class="btn btn-secondary">Move to Currently Reading</button>
       </form>`;

  const content = `
    <div style="margin-bottom: 1rem;">
      <a href="/" class="btn btn-secondary" style="font-size: 0.85rem; padding: 0.35rem 0.7rem;">&larr; All Books</a>
    </div>

    <article class="card">
      <div style="display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; flex-wrap: wrap;">
        <div>
          <h1 style="margin: 0 0 0.25rem 0; font-size: 1.6rem;">${escapeHtml(book.title)}</h1>
          <div class="book-author" style="font-size: 1.05rem;">by ${escapeHtml(book.author)}</div>
        </div>
        <div style="display: flex; align-items: center; gap: 0.5rem;">
          ${statusBadge}
          ${toggleStatusButton}
        </div>
      </div>

      <section style="margin-top: 1.5rem;">
        <h2 style="font-size: 1rem; margin-bottom: 0.5rem;">My Notes</h2>
        <div class="notes-box" id="book-notes">${book.notes ? escapeHtml(book.notes) : '<span style="color: var(--muted);">No notes yet.</span>'}</div>

        <details style="margin-top: 0.75rem;">
          <summary style="cursor: pointer; font-size: 0.9rem; font-weight: 600; color: var(--accent);">Edit Notes &amp; Details</summary>
          <form method="POST" action="/books/${encodeURIComponent(book.id)}/update" style="margin-top: 0.75rem;">
            <div class="form-grid">
              <div class="field">
                <label for="edit-title">Title</label>
                <input type="text" id="edit-title" name="title" value="${escapeHtml(book.title)}" required />
              </div>
              <div class="field">
                <label for="edit-author">Author</label>
                <input type="text" id="edit-author" name="author" value="${escapeHtml(book.author)}" required />
              </div>
            </div>
            <div class="field">
              <label for="edit-notes">Notes</label>
              <textarea id="edit-notes" name="notes">${escapeHtml(book.notes)}</textarea>
            </div>
            <button type="submit" class="btn">Save Changes</button>
          </form>
        </details>
      </section>

      <div class="share-bar">
        <label for="share-link" style="margin: 0; white-space: nowrap;">Share link:</label>
        <input type="text" id="share-link" class="share-input" readonly value="${escapeHtml(shareUrl)}" onclick="this.select()" />
        <button type="button" class="btn btn-secondary" id="copy-link-btn" onclick="navigator.clipboard?.writeText(document.getElementById('share-link').value).then(() => { this.textContent = 'Copied!'; setTimeout(() => { this.textContent = 'Copy Link'; }, 1500); })">Copy Link</button>
      </div>
    </article>
  `;

  return renderLayout(`${book.title} — Reading Log`, content);
}

export function createApp({ dataFile } = {}) {
  const store = new BookStore(dataFile);

  const server = http.createServer(async (req, res) => {
    try {
      const host = req.headers.host || 'localhost';
      const protocol = req.headers['x-forwarded-proto'] || 'http';
      const origin = `${protocol}://${host}`;
      const url = new URL(req.url || '/', origin);
      const pathname = url.pathname;
      const method = req.method || 'GET';

      // API Routes
      if (pathname === '/api/books' && method === 'GET') {
        const books = await store.getAll();
        return sendJson(res, 200, books);
      }

      if (pathname === '/api/books' && method === 'POST') {
        const body = await parseBody(req);
        if (!body.title || !body.author || !String(body.title).trim() || !String(body.author).trim()) {
          return sendJson(res, 400, { error: 'Title and author are required' });
        }
        const book = await store.addBook(body);
        return sendJson(res, 201, book);
      }

      const apiBookMatch = pathname.match(/^\/api\/books\/([^/]+)$/);
      if (apiBookMatch) {
        const id = decodeURIComponent(apiBookMatch[1]);
        if (method === 'GET') {
          const book = await store.getById(id);
          if (!book) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, book);
        }
        if (method === 'PATCH' || method === 'PUT') {
          const body = await parseBody(req);
          const updated = await store.updateBook(id, body);
          if (!updated) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, updated);
        }
        if (method === 'DELETE') {
          const removed = await store.deleteBook(id);
          if (!removed) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 204, '');
        }
      }

      const apiFinishMatch = pathname.match(/^\/api\/books\/([^/]+)\/finish$/);
      if (apiFinishMatch && method === 'POST') {
        const id = decodeURIComponent(apiFinishMatch[1]);
        const updated = await store.updateBook(id, { status: 'finished' });
        if (!updated) return sendJson(res, 404, { error: 'Book not found' });
        return sendJson(res, 200, updated);
      }

      // HTML Routes
      if (pathname === '/' && method === 'GET') {
        const books = await store.getAll();
        return sendHtml(res, 200, renderHomePage(books));
      }

      if (pathname === '/books' && method === 'POST') {
        const body = await parseBody(req);
        if (!body.title || !body.author || !String(body.title).trim() || !String(body.author).trim()) {
          return sendHtml(res, 400, renderLayout('Error', '<p>Title and author are required.</p><a href="/">Back</a>'));
        }
        await store.addBook(body);
        return redirect(res, '/');
      }

      const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
      if (finishMatch && method === 'POST') {
        const id = decodeURIComponent(finishMatch[1]);
        const updated = await store.updateBook(id, { status: 'finished' });
        if (!updated) return sendHtml(res, 404, renderLayout('Not Found', '<p>Book not found.</p><a href="/">Back</a>'));
        const referer = req.headers.referer || '/';
        const redirectTarget = referer.includes(`/books/${id}`) ? `/books/${encodeURIComponent(id)}` : '/';
        return redirect(res, redirectTarget);
      }

      const reopenMatch = pathname.match(/^\/books\/([^/]+)\/reopen$/);
      if (reopenMatch && method === 'POST') {
        const id = decodeURIComponent(reopenMatch[1]);
        const updated = await store.updateBook(id, { status: 'reading' });
        if (!updated) return sendHtml(res, 404, renderLayout('Not Found', '<p>Book not found.</p><a href="/">Back</a>'));
        return redirect(res, `/books/${encodeURIComponent(id)}`);
      }

      const updateMatch = pathname.match(/^\/books\/([^/]+)\/update$/);
      if (updateMatch && method === 'POST') {
        const id = decodeURIComponent(updateMatch[1]);
        const body = await parseBody(req);
        const updated = await store.updateBook(id, body);
        if (!updated) return sendHtml(res, 404, renderLayout('Not Found', '<p>Book not found.</p><a href="/">Back</a>'));
        return redirect(res, `/books/${encodeURIComponent(id)}`);
      }

      const bookPageMatch = pathname.match(/^\/books\/([^/]+)$/);
      if (bookPageMatch && method === 'GET') {
        const id = decodeURIComponent(bookPageMatch[1]);
        const book = await store.getById(id);
        if (!book) {
          return sendHtml(
            res,
            404,
            renderLayout('Book Not Found', '<div class="card"><h1>Book not found</h1><p>This book link may be invalid or removed.</p><a href="/" class="btn">Back to Reading Log</a></div>')
          );
        }
        return sendHtml(res, 200, renderBookPage(book, origin));
      }

      return sendHtml(res, 404, renderLayout('Not Found', '<div class="card"><h1>Page Not Found</h1><a href="/" class="btn">Back Home</a></div>'));
    } catch (err) {
      return sendJson(res, 500, { error: err.message || 'Internal Server Error' });
    }
  });

  return { server, store };
}

