import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { createApp } from '../src/app.js';

describe('Reading Log App', () => {
  let tmpDir;
  let dataFile;
  let server;
  let baseUrl;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'reading-log-test-'));
    dataFile = path.join(tmpDir, 'books.json');
    const app = createApp({ dataFile });
    server = app.server;
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    const address = server.address();
    baseUrl = `http://127.0.0.1:${address.port}`;
  });

  afterEach(async () => {
    await new Promise((resolve) => server.close(resolve));
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it('renders home page with Currently Reading and Finished sections', async () => {
    const res = await fetch(`${baseUrl}/`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Currently Reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Add a Book');
  });

  it('adds a book via form submission, marks it as finished, and persists to JSON across restarts', async () => {
    // 1. Submit form to add a book
    const formBody = new URLSearchParams({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Must not fear.',
    });

    const createRes = await fetch(`${baseUrl}/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: formBody.toString(),
      redirect: 'manual',
    });
    expect(createRes.status).toBe(303);

    // 2. Verify JSON file has the book
    const savedRaw = await fs.readFile(dataFile, 'utf8');
    const savedBooks = JSON.parse(savedRaw);
    expect(savedBooks).toHaveLength(1);
    expect(savedBooks[0].title).toBe('Dune');
    expect(savedBooks[0].author).toBe('Frank Herbert');
    expect(savedBooks[0].notes).toBe('Must not fear.');
    expect(savedBooks[0].status).toBe('reading');

    const bookId = savedBooks[0].id;

    // 3. Visit single book shareable link
    const detailRes = await fetch(`${baseUrl}/books/${bookId}`);
    expect(detailRes.status).toBe(200);
    const detailHtml = await detailRes.text();
    expect(detailHtml).toContain('Dune');
    expect(detailHtml).toContain('Frank Herbert');
    expect(detailHtml).toContain('Must not fear.');
    expect(detailHtml).toContain(`/books/${bookId}`);

    // 4. Mark book as finished
    const finishRes = await fetch(`${baseUrl}/books/${bookId}/finish`, {
      method: 'POST',
      redirect: 'manual',
    });
    expect(finishRes.status).toBe(303);

    // 5. Simulate server restart with the same JSON file
    await new Promise((resolve) => server.close(resolve));
    const restarted = createApp({ dataFile });
    server = restarted.server;
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    baseUrl = `http://127.0.0.1:${server.address().port}`;

    // 6. Verify book is still present and marked finished after restart
    const apiRes = await fetch(`${baseUrl}/api/books`);
    const booksAfterRestart = await apiRes.json();
    expect(booksAfterRestart).toHaveLength(1);
    expect(booksAfterRestart[0].id).toBe(bookId);
    expect(booksAfterRestart[0].status).toBe('finished');
  });

  it('supports JSON API endpoints for adding, viewing, and updating books', async () => {
    const postRes = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'Amaze!',
      }),
    });
    expect(postRes.status).toBe(201);
    const created = await postRes.json();
    expect(created.id).toBeTruthy();

    const getRes = await fetch(`${baseUrl}/api/books/${created.id}`);
    expect(getRes.status).toBe(200);
    const fetched = await getRes.json();
    expect(fetched.title).toBe('Project Hail Mary');

    const patchRes = await fetch(`${baseUrl}/api/books/${created.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'finished', notes: 'Updated note' }),
    });
    expect(patchRes.status).toBe(200);
    const updated = await patchRes.json();
    expect(updated.status).toBe('finished');
    expect(updated.notes).toBe('Updated note');
  });
});

